          ctx.addIssue({ code: "custom", message: "reproduction_time_consort_reflection_invalid" });
        if (
          event.type === "wolf_sorcerer_exchange_committed" ||
          event.type === "wolf_sorcerer_exchange_skipped"
        ) {
          const fact =
            event.type === "wolf_sorcerer_exchange_committed"
              ? readWolfSorcererExchangeFact(event.type, event.payload)
              : readWolfSorcererSkipFact(event.type, event.payload);
          if (!fact || event.audience?.length !== 1 || event.audience[0] !== fact.actorId)
            ctx.addIssue({
              code: "custom",
              message: "reproduction_wolf_sorcerer_audience_invalid",
            });
        }
        if (
          event.type === "trickster_exchange_committed" ||
          event.type === "trickster_exchange_skipped"
        ) {
          const fact =
            event.type === "trickster_exchange_committed"
              ? readTricksterExchangeFact(event.type, event.payload)
              : readTricksterSkipFact(event.type, event.payload);
          if (!fact || event.audience?.length !== 1 || event.audience[0] !== fact.actorId)
            ctx.addIssue({ code: "custom", message: "reproduction_trickster_audience_invalid" });
        }
        if (
          event.type === "exile_target_mapped" &&
          (!readExileMappingFact(event.type, event.payload) || event.audience !== undefined)
        )
          ctx.addIssue({ code: "custom", message: "reproduction_trickster_mapping_invalid" });
        if (event.type === "order_prince_choice_committed") {
          const fact = readOrderPrinceChoiceFact(event.type, event.payload);
          if (!fact || event.audience?.length !== 1 || event.audience[0] !== fact.actorId)
            ctx.addIssue({ code: "custom", message: "reproduction_order_prince_audience_invalid" });
        }
        if (
          event.type === "order_prince_revote_started" &&
          (!readOrderPrinceRevoteFact(event.type, event.payload) || event.audience !== undefined)
        )
          ctx.addIssue({ code: "custom", message: "reproduction_order_prince_reveal_invalid" });
        if (event.type === "magician_exchange_committed") {
          const fact = readMagicianExchangeFact(event.type, event.payload);
          if (!fact || event.audience?.length !== 1 || event.audience[0] !== fact.actorId)
            ctx.addIssue({ code: "custom", message: "reproduction_magician_audience_invalid" });
        }
        if (
          event.type === "death_shot_missed" &&
          (!readDeathShotMissFact(event.type, event.payload) || event.audience !== undefined)
        )
          ctx.addIssue({ code: "custom", message: "reproduction_magician_shot_miss_invalid" });
        if (event.type === "nightmare_fear_committed") {
          const fact = readNightmareFearFact(event.type, event.payload);
          if (!fact || event.audience?.length !== 1 || event.audience[0] !== fact.actorId)
            ctx.addIssue({ code: "custom", message: "reproduction_nightmare_audience_invalid" });
        }

        if (
          [
            "modifier_choice_committed",
            "modifier_choice_skipped",
            "modifier_bonus_resolved",
          ].includes(event.type)
        ) {
          const fact =
            event.type === "modifier_choice_committed"
              ? readModifierChoiceFact(event.type, event.payload)
              : event.type === "modifier_choice_skipped"
                ? readModifierSkipFact(event.type, event.payload)
                : readModifierBonusFact(event.type, event.payload);
          if (!fact || event.audience?.length !== 1 || event.audience[0] !== fact.actorId)
            ctx.addIssue({ code: "custom", message: "reproduction_modifier_owner_invalid" });
        }
        if (
          event.type === "modifier_conflict_resolved" &&
          (!readModifierConflictFact(event.type, event.payload) || event.audience?.length !== 0)
        )
          ctx.addIssue({ code: "custom", message: "reproduction_modifier_conflict_invalid" });
        if ((ANIMAL_DREAM_EVENT_TYPES as readonly string[]).includes(event.type)) {
          const fact = readAnimalDreamFact(event.type, event.payload),
            audience = animalDreamFactAudience(event.type as AnimalDreamEventType);
          if (
            !fact ||
            (audience === "public"
              ? event.audience !== undefined
              : audience === "god"
                ? event.audience?.length !== 0
                : event.audience?.length !== 1 ||
                  event.audience[0] !==
                    ("actorId" in fact.payload ? fact.payload.actorId : undefined))
          )
            ctx.addIssue({ code: "custom", message: "reproduction_animal_fact_invalid" });
        }
        if ((FRAGRANT_PAIR_EVENT_TYPES as readonly string[]).includes(event.type)) {
          const fact = readFragrantPairFact(event.type, event.payload),
            visibility = fragrantPairVisibility(event.type);
          if (
            !fact ||
            (visibility === "god"
              ? event.audience?.length !== 0
              : event.audience?.length !== 1 || event.audience[0] !== fact.actorId)
          )
            ctx.addIssue({ code: "custom", message: "reproduction_fragrant_fact_invalid" });
        }
        if ((NOBLE_SECRET_BODY_EVENT_TYPES as readonly string[]).includes(event.type)) {
          const fact = readNobleSecretBodyFact(event.type, event.payload),
            visibility = nobleSecretBodyVisibility(event.type);
          if (
            !fact ||
            (visibility === "god"
              ? event.audience?.length !== 0
              : visibility === "actor"
                ? event.audience?.length !== 1 || event.audience[0] !== fact.actorId
                : event.audience !== undefined)
          )
            ctx.addIssue({
              code: "custom",
              message: "reproduction_noble_secret_body_fact_invalid",
            });
        }
        if ((RADIANT_ECLIPSE_EVENT_TYPES as readonly string[]).includes(event.type)) {
          const fact = readRadiantEclipseFact(event.type, event.payload),
            expected = fact ? radiantEclipseAudience(event.type, fact) : null;
          if (
            !expected ||
            !Array.isArray(event.audience) ||
            event.audience.length !== expected.length ||
            !expected.every((id, i) => event.audience![i] === id)
          )
            ctx.addIssue({ code: "custom", message: "reproduction_radiant_eclipse_fact_invalid" });
        }
        if ((MIST_RAVEN_EVENT_TYPES as readonly string[]).includes(event.type)) {
          const fact = readMistRavenFact(event.type, event.payload);
          if (
            !fact ||
            ("actorId" in fact &&
              (event.audience?.length !== 1 || event.audience[0] !== fact.actorId))
          )
            ctx.addIssue({ code: "custom", message: "reproduction_mist_raven_fact_invalid" });
        }
        if (
          event.audience !== undefined &&
          !(ANIMAL_DREAM_EVENT_TYPES as readonly string[]).includes(event.type) &&
          !(FRAGRANT_PAIR_EVENT_TYPES as readonly string[]).includes(event.type) &&
          !(NOBLE_SECRET_BODY_EVENT_TYPES as readonly string[]).includes(event.type) &&
          !(RADIANT_ECLIPSE_EVENT_TYPES as readonly string[]).includes(event.type) &&
          !(MIST_RAVEN_EVENT_TYPES as readonly string[]).includes(event.type) &&
          !(WOLF_TEAM_EVENT_TYPES as readonly string[]).includes(event.type) &&
          !(GHOST_BRIDE_EVENT_TYPES as readonly string[]).includes(event.type) &&
          !(DEMON_HUNTER_EVENT_TYPES as readonly string[]).includes(event.type) &&
          event.type !== "nightmare_fear_committed" &&
          event.type !== "modifier_choice_committed" &&
          event.type !== "modifier_choice_skipped" &&
          event.type !== "modifier_conflict_resolved" &&
          event.type !== "modifier_bonus_resolved" &&
          event.type !== "time_consort_lock_committed" &&
          event.type !== "time_consort_lock_skipped" &&
          event.type !== "time_consort_reflected" &&
          event.type !== "wolf_sorcerer_exchange_committed" &&
          event.type !== "wolf_sorcerer_exchange_skipped" &&
          event.type !== "trickster_exchange_committed" &&
          event.type !== "trickster_exchange_skipped" &&
          event.type !== "order_prince_choice_committed" &&
          event.type !== "magician_exchange_committed"
        ) {
          ctx.addIssue({ code: "custom", message: "reproduction_event_audience_invalid" });
        }
      }),
  ),
  operations: z.array(
    z.strictObject({
      scope: z.string(),
      op: z.string(),
      actor_id: positive.optional(),
      event_count: nonnegative.optional(),
      phase: z.string().optional(),
      status: z.string(),
      reason: z.string().optional(),
      input: jsonObject.optional(),
      output: jsonObject.optional(),
    }),
  ),
  termination: z
    .strictObject({
      reason: z.string(),
      winner: z.enum(Camp).nullable(),
      errors: z.array(z.strictObject({ scope: z.enum(FAILURE_SCOPES), name: z.enum(ERROR_NAMES) })),
    })
    .nullable(),
});

/** 先保原版本／严格 envelope 准入，再按固定独立装配审核角色与板子；审核不执行游戏规则。 */
export function parseReproductionRecord(value: unknown): ReproductionRecord {
  // 新封装先按显式格式解包，历史裸 Tape 仍走下面原 schema 2／第一失败顺序。
  value = unwrapRecordingEnvelope(value, "strict_reproduction").payload;
  if (
    value &&
    typeof value === "object" &&
    "schemaVersion" in value &&
    value.schemaVersion !== REPRODUCTION_SCHEMA_VERSION
  )
    throw new Error("reproduction_schema_not_supported");
  const parsed = schema.safeParse(value);
  if (!parsed.success) throw new Error("reproduction_record_invalid");
  const result = parsed.data as unknown as ReproductionRecord;
  verifyReproductionMechanisms(result);
  return result;
}

/**
 * 负责 checkpoint 玩家记录的有序编码。输入为同一 World、完整／失败模式和最初动物审计快照；
 * 输出保留恶魔原体优先；私有状态由数据 owner 在原字段位置编码，其余完整字段和顺序仍归本装配。
 * 原体 descriptor、JSON、重复组件读取和 fallback 克隆各在原表达式处执行；不修改 live 状态。
 * 壁上便签、恋人、处罚、胜利、投票、警徽和印记贡献只编码，不推导新规则或授予行动权限。
 */
import {
  COMPONENT,
  type BadgeComponent,
  type IdentityComponent,
  type RoleComponent,
  type StatusMarksComponent,
  type VotingRightComponent,
  type VictoryComponent,
  type World,
} from "../../core";
import type { RecordedCheckpoint } from "../reproduction";
import type { prepareAnimalCheckpoint } from "./authority-snapshots";
import { auditData } from "./animal-audit";
import { encodeCheckpointPrivateState } from "./private-state-codec";
import { aliveLifeDescriptor } from "../../core/domain/components/alive";
import {
  animalOriginalAuditPlayer,
  animalOriginalAuditIds,
} from "../../game/mechanisms/roles/animal_dream/roster";
import { demonHunterCheckpointPlayers } from "../../game/mechanisms/roles/demon_hunter/authority";
import { weddingAuditPlayer } from "../../game/mechanisms/roles/ghost_bride/authority";
import {
  projectLonelyGirlVictory,
  projectLonelyGirlAuditPlayer,
} from "../../game/mechanisms/roles/lonely_girl/lifecycle";
import { projectWallNote } from "../../game/mechanisms/events/wall_notes/authority";

/** 同一调用按原权威优先级编码；数据可供归档核验，不能替代运行时原体或库存许可。 */
export function capturePlayerContributions(
  world: World,
  complete: boolean,
  animal: ReturnType<typeof prepareAnimalCheckpoint>,
): RecordedCheckpoint["players"] {
  return (
    // 恶魔板的完整原参与者快照优先返回；非 null 时不读取后面的席位名单或其它贡献。
    demonHunterCheckpointPlayers(world, complete) ??
    (animalOriginalAuditIds(world) ?? world.entityIds()).map((id) => {
      // 动物失败审计保留最初授权身体；身份／票权／警徽从捕获数据解码，普通路径才读取当前组件。
      const original = animal ? animalOriginalAuditPlayer(world, id) : null;
      const identity = original
        ? (JSON.parse(original.identityJson) as IdentityComponent)
        : world.getComponent(id, COMPONENT.Identity)!;
      const role = original?.scope.role ?? world.getComponent(id, COMPONENT.Role)!;
      const badge = original
        ? (auditData(original.audit.badge, [
            "isSheriff",
            "destroyed",
            "voteWeight",
            "handoffPolicy",
          ]) as BadgeComponent)
        : world.getComponent(id, COMPONENT.Badge)!;
      const vote = original
        ? (auditData(original.audit.vote, ["weight", "canVote"]) as VotingRightComponent)
        : world.getComponent(id, COMPONENT.VotingRight)!;
      const weddingAudit = weddingAuditPlayer(world, id, !complete);
      // 婚约审计优先于孤女审计；记录覆盖与历史Camp保原优先级，普通fallback才晚读实际Camp。
      const audit = weddingAudit ?? projectLonelyGirlAuditPlayer(world, id);
      const wall = projectWallNote(world, id);
      const wallNote = wall
        ? {
            instanceId: wall.instanceId,
            source: { ...wall.source },
            remaining: wall.remaining,
            expired: wall.expired,
          }
        : undefined;
      return {
        id,
        seat: identity.seat,
        name: identity.name,
        role: (original?.scope.roleId as RoleComponent["role"]) ?? audit?.role ?? role.role,
        camp: original?.scope.campValue ?? audit?.camp ?? world.getComponent(id, COMPONENT.Camp)!.camp,
        alive: original
          ? aliveLifeDescriptor(original.scope.life)!.get!.call(original.scope.life)
          : (audit?.alive ?? world.getComponent(id, COMPONENT.Alive)!.alive),
        // 原特殊审计优先级与整容器克隆归数据 owner；这里只在原字段位置传入已求出的引用。
        privateState: encodeCheckpointPrivateState(world, id, complete, animal, original, role, audit),
        ...(wallNote ? { wallNote } : {}),
        // 可选组件先判断、再现场读取并克隆；getter／克隆失败仍从原表达式传播，不补空记录。
        ...(world.getComponent(id, COMPONENT.DebatePenalty)
          ? {
              debatePenalty: structuredClone(world.getComponent(id, COMPONENT.DebatePenalty)!),
            }
          : {}),
        ...(world.getComponent(id, COMPONENT.Lovers)
          ? {
              lovers: structuredClone(world.getComponent(id, COMPONENT.Lovers)!),
            }
          : {}),
        // 原动物、婚约及孤女胜利记录先于普通组件克隆；失败审计和当前成功记录不可互换来源。
        victory:
          (original ? (JSON.parse(original.victoryJson) as VictoryComponent) : null) ??
          (weddingAudit ? { affiliations: weddingAudit.victory } : null) ??
          projectLonelyGirlVictory(world, id) ??
          structuredClone(world.getComponent(id, COMPONENT.Victory)!),
        vote: { weight: vote.weight, canVote: vote.canVote },
        badge: {
          isSheriff: badge.isSheriff,
          destroyed: badge.destroyed,
          voteWeight: badge.voteWeight,
          ...(badge.handoffPolicy ? { handoffPolicy: badge.handoffPolicy } : {}),
        },
        marks: (
          (original?.audit.marks as StatusMarksComponent | undefined) ??
          world.getComponent(id, COMPONENT.StatusMarks)!
        ).values(),
      };
    })
  );
}

/**
 * 向后端和浏览器公开原 schema 2 复盘、历史转换与显式封装 reader；输入为纯数据归档。
 * 输出保留原规范化 document，旧未声明／v1／v2 reader 规则与原文不变；新封装身份不表示可执行授权。
 * 游戏结算与严格来源兼容仍由后端实际执行器负责，本出口不导入 Node、World 或 renderer。
 */
import { isRecord, assertField, assertSerializedData, ReplayDocumentValidationError } from "./validation";
export { ReplayDocumentValidationError } from "./validation";
import { isLocale, type Locale, type SealedVictoryResult } from "@ai-werewolf-arena/game-contract";
import { unwrapRecordingEnvelope, type RecordingIdentities } from "./archive-envelope";
import { readVictoryResult } from "./outcomes";
import {
  legacyPhaseId,
  legacyStageId,
  legacyRoleId,
  legacyCampId,
  legacyResultReasonId,
} from "./legacy_aliases";
export * from "./legacy_aliases";
export const REPLAY_SCHEMA_VERSION = 2 as const;
export * from "./inspection";
export * from "./gravekeeper";
export * from "./outcomes";

/**
 * 浏览器与视频消费的公开复盘数据形状；展示视图不充当已持久化完整归档。
 *
 * `god` 为完整裁判视角，包含每个角色和所有公开事件，
 * 也支持仍进行中的对局；执行来源与版本声明由新 envelope 独立记录。
 */
export type ReplayPerspective = "god";

export interface ReplayEvent {
  seq: number;
  timestamp: string;
  phase: string;
  day: number;
  stage?: string;
  type: string;
  payload: Record<string, unknown>;
}

export interface ReplayDocument {
  schemaVersion: typeof REPLAY_SCHEMA_VERSION;
  sessionId: string;
  perspective: ReplayPerspective;
  meta: {
    locale?: Locale;
    board: string;
    startedAt: string;
    endedAt: string;
  };
  result: {
    winner: string | null;
    reason: string | null;
    /** 明确的引擎判胜，与执行结束原因分别记录。 */
    decision?: SealedVictoryResult;
  };
  players: Array<{
    player_id: number;
    role: string;
    camp: string;
    name?: string;
  }>;
  events: ReplayEvent[];
}

/** 校验未筛选的原规范 document，事件序号从一开始；不推导游戏规则。 */
function assertReplayShape(
  value: unknown,
): asserts value is Omit<ReplayDocument, "schemaVersion"> & { schemaVersion?: unknown } {
  if (
    !isRecord(value) ||
    value.perspective !== "god" ||
    typeof value.sessionId !== "string" ||
    !Array.isArray(value.events)
  ) {
    throw new ReplayDocumentValidationError("invalid_document", "document");
  }
  if (!isRecord(value.meta) || !isRecord(value.result) || !Array.isArray(value.players)) {
    throw new ReplayDocumentValidationError("missing_fields", "meta/result/players");
  }

  assertField(value.meta.locale === undefined || isLocale(value.meta.locale), "meta.locale");
  assertField(typeof value.meta.board === "string", "meta.board");
  assertField(typeof value.meta.startedAt === "string", "meta.startedAt");
  assertField(typeof value.meta.endedAt === "string", "meta.endedAt");
  assertField(
    value.result.winner === null || typeof value.result.winner === "string",
    "result.winner",
  );
  assertField(
    value.result.reason === null || typeof value.result.reason === "string",
    "result.reason",
  );

  const playerIds = new Set<number>();
  for (let index = 0; index < value.players.length; index += 1) {
    const player: unknown = value.players[index];
    const path = `players[${index}]`;
    assertField(isRecord(player), path);
    assertField(
      typeof player.player_id === "number" &&
        Number.isSafeInteger(player.player_id) &&
        player.player_id > 0,
      `${path}.player_id`,
    );
    assertField(!playerIds.has(player.player_id), `${path}.player_id`);
    playerIds.add(player.player_id);
    assertField(typeof player.role === "string", `${path}.role`);
    assertField(typeof player.camp === "string", `${path}.camp`);
    assertField(player.name === undefined || typeof player.name === "string", `${path}.name`);
  }

  for (let index = 0; index < value.events.length; index += 1) {
    const event: unknown = value.events[index];
    const path = `events[${index}]`;
    assertField(isRecord(event), path);
    assertField(event.seq === index + 1, `${path}.seq`);
    assertField(typeof event.timestamp === "string", `${path}.timestamp`);
    assertField(typeof event.phase === "string", `${path}.phase`);
    assertField(
      typeof event.day === "number" && Number.isSafeInteger(event.day) && event.day >= 0,
      `${path}.day`,
    );
    assertField(event.stage === undefined || typeof event.stage === "string", `${path}.stage`);
    assertField(typeof event.type === "string", `${path}.type`);
    assertField(isRecord(event.payload), `${path}.payload`);
  }
  const decision = Object.getOwnPropertyDescriptor(value.result, "decision");
  if (decision) {
    assertField("value" in decision && decision.enumerable === true, "result.decision");
    const parsed = readVictoryResult(decision.value, [...playerIds]);
    assertField(parsed.winner === value.result.winner, "result.winner");
  }
  const explicit: SealedVictoryResult[] = [];
  if (decision && "value" in decision)
    explicit.push(readVictoryResult(decision.value, [...playerIds]));
  for (const event of value.events) {
    if (
      event.type !== "game_over" ||
      !isRecord(event.payload) ||
      (!Object.hasOwn(event.payload, "outcome") && !Object.hasOwn(event.payload, "decidedAt"))
    )
      continue;
    assertSerializedData(event.payload, "events.game_over.payload");
    try {
      explicit.push(readVictoryResult(event.payload, [...playerIds]));
    } catch {
      /* 独立非法终局事实继续保留为未知原事件，不生成替代判胜。 */
    }
  }
  if (explicit.length > 1)
    assertField(
      explicit.every((item) => JSON.stringify(item) === JSON.stringify(explicit[0])),
      "result.decision_terminal_mismatch",
    );
}

/** 原 canonical v2 writer 契约；历史文件及显式新封装由 reader 单独判版本。 */
export function assertReplayDocument(value: unknown): asserts value is ReplayDocument {
  if (value !== null && typeof value === "object") assertSerializedData(value, "document");
  assertReplayShape(value);
  if (value.schemaVersion !== REPLAY_SCHEMA_VERSION)
    throw new ReplayDocumentValidationError("unsupported_version", "schemaVersion");
}

/** 只读转换，先判封装和内层版本再解释历史别名；昵称、发言等用户原文不改写。 */
export function readReplayDocument(value: unknown): ReplayDocument {
  if (value !== null && typeof value === "object") assertSerializedData(value, "document");
  value = unwrapRecordingEnvelope(value, "public_replay").payload;
  if (!isRecord(value)) throw new ReplayDocumentValidationError("invalid_document", "document");
  const version = value.schemaVersion;
  if (version !== undefined && version !== 1 && version !== REPLAY_SCHEMA_VERSION)
    throw new ReplayDocumentValidationError("unsupported_version", "schemaVersion");
  assertReplayShape(value);
  if (version === REPLAY_SCHEMA_VERSION) {
    const result = structuredClone(value);
    assertReplayDocument(result);
    return result as ReplayDocument;
  }
  const result = structuredClone(value) as ReplayDocument;
  result.schemaVersion = REPLAY_SCHEMA_VERSION;
  result.players = result.players.map((player) => ({
    ...player,
    role: legacyRoleId(player.role),
    camp: legacyCampId(player.camp),
  }));
  result.result.winner = result.result.winner === null ? null : legacyCampId(result.result.winner);
  result.result.reason =
    result.result.reason === null ? null : legacyResultReasonId(result.result.reason);
  result.events = result.events.map((event) => {
    const payload = { ...event.payload };
    if (event.type === "phase_changed" && typeof payload.phase === "string")
      payload.phase = legacyPhaseId(payload.phase);
    if (event.type === "game_over" || event.type === "phase_changed") {
      if (typeof payload.winner === "string") payload.winner = legacyCampId(payload.winner);
      if (typeof payload.reason === "string") payload.reason = legacyResultReasonId(payload.reason);
    }
    if (event.type === "god_private_game_info" && Array.isArray(payload.players))
      payload.players = payload.players.map((player) =>
        isRecord(player)
          ? {
              ...player,
              ...(typeof player.role === "string" ? { role: legacyRoleId(player.role) } : {}),
              ...(typeof player.camp === "string" ? { camp: legacyCampId(player.camp) } : {}),
            }
          : player,
      );
    return {
      ...event,
      phase: legacyPhaseId(event.phase),
      ...(event.stage === undefined ? {} : { stage: legacyStageId(event.stage) }),
      payload,
    };
  });
  assertReplayDocument(result);
  return result;
}

